#include <bits/stdc++.h>
using namespace std;

int longestArithmeticProgression(vector<int>& nums) {
    int n = nums.size();
    if (n <= 2) return n;

    sort(nums.begin(), nums.end());
    vector<vector<int>> dp(n, vector<int>(n, 2));
    int ans = 2;

    for (int j = n - 2; j >= 1; j--) {
        int i = j - 1, k = j + 1;
        while (i >= 0 && k < n) {
            if (nums[i] + nums[k] < 2 * nums[j]) {
                k++;
            } else if (nums[i] + nums[k] > 2 * nums[j]) {
                i--;
            } else {
                dp[j][k] = dp[i][j] + 1;
                ans = max(ans, dp[j][k]);
                i--;
                k++;
            }
        }
    }
    return ans;
}

