    if (n <= 2) {
        printf("%d\n", n);
        free(a);
        return 0;
    }

    // dp[i][j] = length of longest AP ending with a[j], a[i]
    int **dp = (int**)malloc(n * sizeof(int*));
    for (int i = 0; i < n; i++) {
        dp[i] = (int*)malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) dp[i][j] = 2;
    }

    int ans = 2;

    for (int i = 2; i < n; i++) {
        for (int j = 1; j < i; j++) {
            int need = 2 * a[j] - a[i];
            int k = bsearch_find(a, j, need);
            if (k >= 0) {
                dp[i][j] = dp[j][k] + 1;
            } else {
                dp[i][j] = 2;
            }
            if (dp[i][j] > ans) ans = dp[i][j];
        }
    }

    printf("%d\n", ans);

    for (int i = 0; i < n; i++) free(dp[i]);
