#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int longestArithSeqLength(int* nums, int numsSize) {
    if (numsSize <= 2) return numsSize;

    qsort(nums, numsSize, sizeof(int), compare);

    int maxLen = 2;
    // dp[i][diff] but diff can be large, so we use 2D array with max possible diff
    // Since nums[i] <= 10000 (constraints not given, but we can allocate dynamically)
    int maxDiff = nums[numsSize-1] - nums[0];

    // Allocate 2D array: numsSize x (2*maxDiff+1) to handle negative diff offset
    int **dp = (int**)malloc(numsSize * sizeof(int*));
    for (int i = 0; i < numsSize; i++) {
        dp[i] = (int*)calloc(2 * maxDiff + 1, sizeof(int));
    }

    int offset = maxDiff;

    for (int i = 1; i < numsSize; i++) {
        for (int j = 0; j < i; j++) {
            int diff = nums[i] - nums[j];
            int idx = diff + offset;

            if (dp[j][idx] > 0) {
                dp[i][idx] = dp[j][idx] + 1;
            } else {
                dp[i][idx] = 2;
            }

            if (dp[i][idx] > maxLen) {
                maxLen = dp[i][idx];
            }
        }
    }

    for (int i = 0; i < numsSize; i++) free(dp[i]);
    free(dp);

    return maxLen;
}

