static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    long long *a = (long long *)malloc((size_t)n * sizeof(long long));
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

    if (n <= 2) {
        printf("%d\n", n);
        free(a);
        return 0;
    }

    qsort(a, n, sizeof(long long), cmp_ll);

    /* dp[i][j] = length of LLAP with a[i], a[j] as first two elements (i < j) */
    int *dp = (int *)malloc((size_t)n * (size_t)n * sizeof(int));
    #define DP(i,j) dp[(size_t)(i) * n + (j)]

    for (int i = 0; i < n; i++) DP(i, n - 1) = 2;

    int ans = 2;

    for (int j = n - 2; j >= 1; j--) {
        int i = j - 1;
        int k = j + 1;

        while (i >= 0 && k <= n - 1) {
            long long left = a[i] + a[k];
            long long mid2 = 2LL * a[j];

            if (left < mid2) {
                k++;
            } else if (left > mid2) {
                DP(i, j) = 2;
                i--;
            } else {
                DP(i, j) = DP(j, k) + 1;
                if (DP(i, j) > ans) ans = DP(i, j);
                i--;
                k++;
            }
        }

        while (i >= 0) {
            DP(i, j) = 2;
            i--;
        }
    }

    printf("%d\n", ans);

    free(dp);
    free(a);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<Integer> list = new ArrayList<>();
        while (sc.hasNextInt()) {
            list.add(sc.nextInt());
        }

        int n = list.size();
        if (n == 0) {
            System.out.println(0);
            return;
        }
        if (n == 1) {
            System.out.println(1);
            return;
        }

        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = list.get(i);
        Arrays.sort(arr);

        // Map from value to index
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < n; i++) indexMap.put(arr[i], i);

        // dp[i][j] = length of longest AP ending with arr[i], arr[j]
        int[][] dp = new int[n][n];
        int ans = 2;

        for (int j = 1; j < n; j++) {
            for (int i = 0; i < j; i++) {
                int need = 2 * arr[i] - arr[j];
                if (indexMap.containsKey(need)) {
                    int k = indexMap.get(need);
                    // k must be < i since need < arr[i] < arr[j] (if need < arr[i])
                    // need = 2*arr[i] - arr[j], arr[j] > arr[i] => need < arr[i]
                    // so k < i guaranteed since array is sorted
                    dp[i][j] = dp[k][i] + 1;
                } else {
                    dp[i][j] = 2;
                }
                ans = Math.max(ans, dp[i][j]);
            }
        }

        System.out.println(ans);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = sc.nextInt();
        }

        // If less than 2 elements, longest AP length = n
        if (n <= 2) {
            System.out.println(n);
            return;
        }

        Arrays.sort(nums);

        // dp[i] = map of difference -> length of AP ending at i
        Map<Integer, Integer>[] dp = new HashMap[n];
        for (int i = 0; i < n; i++) {
            dp[i] = new HashMap<>();
        }

        int maxLen = 2;

        for (int j = 0; j < n; j++) {
            for (int i = 0; i < j; i++) {
                int diff = nums[j] - nums[i];
                // length of AP ending at i with same diff
                int len = dp[i].getOrDefault(diff, 1) + 1;
                dp[j].put(diff, len);
                maxLen = Math.max(maxLen, len);
            }
        }

        System.out.println(maxLen);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer first = fs.nextIntOrNull();
        if (first == null) return;

        int n = first;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextInt();

        if (n <= 2) {
            System.out.println(n);
            return;
        }

        Arrays.sort(a);

        int[][] dp = new int[n][n];
        int ans = 2;

        for (int j = n - 2; j >= 1; j--) {
            int i = j - 1;
            int k = j + 1;

            while (i >= 0 && k < n) {
                long left = (long) a[i] + a[k];
                long mid = 2L * a[j];

                if (left < mid) {
                    k++;
                } else if (left > mid) {
                    dp[i][j] = 2;
                    i--;
                } else {
                    dp[i][j] = dp[j][k] + 1;
                    ans = Math.max(ans, dp[i][j]);
                    i--;
                    k++;
                }
            }

            while (i >= 0) {
                dp[i][j] = 2;
                i--;
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntOrNull() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return nextIntOrNull();
        }
    }
}
